#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define pb emplace_back
#define ull unsigned long long
#define mp make_pair
const int MAX_NODES = 50005;
const ll INF = 1000000007LL;

int readInt() {
    int X = 0, w = 0;
    char ch = 0;
    while (!isdigit(ch)) { w |= ch == '-'; ch = getchar(); }
    while (isdigit(ch)) X = (X << 3) + (X << 1) + (ch ^ 48), ch = getchar();
    return w ? -X : X;
}

struct Edge {
    int from, to, capacity, flow, cost;
    Edge(int f, int t, int c, int fl, int co) : from(f), to(t), capacity(c), flow(fl), cost(co) {}
};

ll n, m, K;
int A[MAX_NODES];
int src, sink;

struct MCMF {
    int nodeCount;
    vector<Edge> edges;
    vector<int> adj[MAX_NODES];
    bool inq[MAX_NODES];
    int dist[MAX_NODES], parentEdge[MAX_NODES], bottleneck[MAX_NODES];

    void init(int n) {
        nodeCount = n;
        for (int i = 0; i <= n; ++i) adj[i].clear();
        edges.clear();
    }

    void addEdge(int u, int v, int cap, int cost) {
        edges.emplace_back(u, v, cap, 0, cost);
        edges.emplace_back(v, u, 0, 0, -cost);
        int idx = edges.size();
        adj[u].pb(idx - 2);
        adj[v].pb(idx - 1);
    }

    bool spfa(int s, int t, int &totalFlow, int &totalCost) {
        fill(dist, dist + t + 1, INF);
        fill(inq, inq + t + 1, false);
        dist[s] = 0;
        inq[s] = true;
        bottleneck[s] = INF;
        queue<int> q;
        q.push(s);

        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;

            for (int eid : adj[u]) {
                Edge& e = edges[eid];
                if (e.capacity > e.flow && dist[e.to] > dist[u] + e.cost) {
                    dist[e.to] = dist[u] + e.cost;
                    parentEdge[e.to] = eid;
                    bottleneck[e.to] = min(bottleneck[u], e.capacity - e.flow);
                    if (!inq[e.to]) {
                        inq[e.to] = true;
                        q.push(e.to);
                    }
                }
            }
        }

        if (dist[t] == INF) return false;
        totalFlow += bottleneck[t];
        totalCost += dist[t] * bottleneck[t];
        int cur = t;
        while (cur != s) {
            int eid = parentEdge[cur];
            edges[eid].flow += bottleneck[t];
            edges[eid ^ 1].flow -= bottleneck[t];
            cur = edges[eid].from;
        }
        return true;
    }

    int getMinCost(int s, int t) {
        int flow = 0, cost = 0;
        while (spfa(s, t, flow, cost));
        return cost;
    }
} solver;

int main() {
    int c, d_val;
    cin >> n >> m >> K >> c >> d_val;

    for (int i = 1; i <= K; ++i) {
        scanf("%d", &A[i]);
    }

    src = 0;
    sink = n * 100 + 1;

    for (int i = 1; i <= K; ++i) {
        solver.addEdge(src, 1 + (A[i] - 1) * 100, 1, 0);
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < 100; ++j) {
            int base = (i - 1) * 100LL;
            solver.addEdge(base + j, base + j + 1, INT_MAX, c);
        }
    }

    for (int i = 1; i <= 100; ++i) {
        solver.addEdge(i, sink, INT_MAX, 0);
    }

    while (m--) {
        int x, y;
        scanf("%d%d", &x, &y);
        for (int i = 1; i < 100; ++i) {
            int u = (x - 1) * 100 + i;
            int v = (y - 1) * 100 + i + 1;
            for (int j = 1; j <= 50; ++j) {
                int weight = d_val * (j * j - (j - 1) * (j - 1)) + c;
                solver.addEdge(u, v, 1, weight);
            }
        }

        for (int i = 1; i < 100; ++i) {
            int u = (y - 1) * 100 + i;
            int v = (x - 1) * 100 + i + 1;
            for (int j = 1; j <= 50; ++j) {
                int weight = d_val * (j * j - (j - 1) * (j - 1)) + c;
                solver.addEdge(u, v, 1, weight);
            }
        }
    }

    printf("%d\n", solver.getMinCost(src, sink));
    return 0;
}
